import {SqliteAgentRuns,SqliteAgentTokenBudget,SqliteAgentBudgetRecoveryDiscovery,AgentBudgetRecovery,AgentBudgetRecoveryWorker,AgentBudgetRecoveryCoordinator,createBudgetHttpsVerifier} from '../../dist/index.js';
const [path,url]=process.argv.slice(2),scope={tenantId:'tenant',agentId:'agent'},actor={tenantId:'tenant',principalId:'operator'},target={scope,runId:'run',maxTokens:100},runs=new SqliteAgentRuns(path),discovery=new SqliteAgentBudgetRecoveryDiscovery(path,{scope,authorize:()=>true}),errors=[];let budget;
try{const verify=createBudgetHttpsVerifier({target,url,bearerToken:'a'.repeat(32),timeoutMs:5000,maxPending:1,interpret:(body,context)=>body&&body.found===true&&body.callId===context.callId&&body.currency===context.cost?.currency?{usedTokens:body.usedTokens,usedCostMicros:body.usedCostMicros}:undefined}),coordinator=new AgentBudgetRecoveryCoordinator({scope,actor,discovery,maxRunsPerPass:5,pollMs:100,authorize:()=>true,open:candidate=>{const selected=new SqliteAgentTokenBudget(path,{scope,runId:candidate.runId,leaseToken:'retired-token',maxTokens:100,cost:{currency:'USD',maxMicros:1000},clock:()=>110}),recovery=new AgentBudgetRecovery({budget:selected,target:{...target,runId:candidate.runId},authorize:()=>true,verify}),worker=new AgentBudgetRecoveryWorker({runs,recovery,scope,runId:candidate.runId,actor,reference:()=> 'provider-case',maxPerPass:5,pollMs:100,onError:error=>errors.push(error.message)});return {worker,close:()=>selected.close()};},onError:error=>errors.push(error.message)});const count=await coordinator.runOnce();await coordinator.stop();budget=new SqliteAgentTokenBudget(path,{scope,runId:'run',leaseToken:'retired-token',maxTokens:100,cost:{currency:'USD',maxMicros:1000},clock:()=>110});process.send?.({count,outcome:count?'reconciled':'unknown',errors,call:budget.get('call'),cost:budget.getCost('call'),evidence:budget.reconciliationHistory()});}catch(error){process.send?.({error:String(error)});process.exitCode=1;}finally{budget?.close();discovery.close();runs.close();}
